package com.railway.servlet;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;import java.util.*;import com.railway.util.DB;
public class AdminServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try(Connection c=DB.getConnection()){for(String key:List.of("users","trains","bookings")){String sql=switch(key){case "users"->"SELECT id,full_name,email,role FROM users ORDER BY id DESC LIMIT 100";case "trains"->"SELECT id,train_number,train_name,source,destination,active,capacity FROM trains ORDER BY id DESC";default->"SELECT pnr,status,total_fare,passenger_count FROM bookings ORDER BY created_at DESC LIMIT 100";};List<Map<String,Object>> list=new ArrayList<>();try(Statement st=c.createStatement();ResultSet x=st.executeQuery(sql)){ResultSetMetaData md=x.getMetaData();while(x.next()){Map<String,Object> m=new LinkedHashMap<>();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),x.getObject(i));list.add(m);}}r.setAttribute(key,list);}}catch(Exception e){getServletContext().log("Admin dashboard failed",e);r.setAttribute("error","Dashboard data unavailable.");}r.getRequestDispatcher("/admin/dashboard.jsp").forward(r,s);}}
